import itertools
import random

n = 16
fixed_edges = [(11,15), (3,15), (5,15)]

# Let's try a constructive approach
# We'll maintain the graph and check girth

def has_cycle_of_length_at_most(graph, max_len):
    """Check if graph has any cycle of length <= max_len"""
    # BFS from each vertex
    adj = {i: set() for i in range(n)}
    for u, v in graph:
        adj[u].add(v)
        adj[v].add(u)

    for start in range(n):
        # BFS to find shortest cycle through start
        # We'll do a DFS with depth limit
        visited = {start: 0}
        stack = [(start, -1, 0)]
        while stack:
            v, parent, depth = stack.pop()
            for u in adj[v]:
                if u == parent:
                    continue
                if u == start and depth + 1 >= 3 and depth + 1 <= max_len:
                    return True
                if u not in visited:
                    visited[u] = depth + 1
                    if depth + 1 < max_len:
                        stack.append((u, v, depth + 1))
                elif depth + visited[u] + 1 >= 3 and depth + visited[u] + 1 <= max_len:
                    # Found a cycle through start
                    return True
    return False

def girth(graph):
    """Compute girth of graph"""
    adj = {i: set() for i in range(n)}
    for u, v in graph:
        adj[u].add(v)
        adj[v].add(u)

    min_cycle = float('inf')
    for start in range(n):
        # BFS
        dist = {start: 0}
        parent = {start: -1}
        queue = [start]
        while queue:
            v = queue.pop(0)
            for u in adj[v]:
                if u == parent[v]:
                    continue
                if u not in dist:
                    dist[u] = dist[v] + 1
                    parent[u] = v
                    queue.append(u)
                elif u != parent[v]:
                    # Found a cycle
                    cycle_len = dist[v] + dist[u] + 1
                    if cycle_len < min_cycle:
                        min_cycle = cycle_len
    return min_cycle

