    # Try to add more edges
    all_possible = [(i,j) for i in range(n) for j in range(i+1,n) if (i,j) not in fixed_edges]
    random.shuffle(all_possible)

    for u, v in all_possible:
        # Check if adding this edge creates a cycle of length < 8
        test_graph = graph + [(u,v)]
        if not has_cycle_of_length_at_most(test_graph, 7):
