def compute_girth(graph, n):
    adj = {i: set() for i in range(n)}
    for u, v in graph:
        adj[u].add(v)
        adj[v].add(u)

    min_cycle = float('inf')
    for start in range(n):
        # BFS to find shortest cycle through start
        dist = {start: 0}
        parent = {start: -1}
        queue = [start]
        while queue:
            v = queue.pop(0)
            for u in adj[v]:
                if u == parent[v]:
                    continue
                if u not in dist:
                    dist[u] = dist[v] + 1
                    parent[u] = v
                    queue.append(u)
                elif u != parent[v]:
                    # Found a cycle: v -> ... -> start -> ... -> u -> v
                    # Actually, we found a back edge (v,u) where u is already visited
                    # The cycle length is dist[v] + dist[u] + 1
                    cycle_len = dist[v] + dist[u] + 1
                    if cycle_len < min_cycle:
                        min_cycle = cycle_len
