def find_any_short_cycle(graph, n, max_len):
    adj = {i: set() for i in range(n)}
    for u, v in graph:
        adj[u].add(v)
        adj[v].add(u)

    # Use DFS to find cycles
    for start in range(n):
        # DFS with path tracking
        stack = [(start, -1, [start])]
        while stack:
            v, parent, path = stack.pop()
            for u in adj[v]:
                if u == parent:
                    continue
                if u == start and len(path) >= 3 and len(path) <= max_len:
                    return path + [start]
                if u not in path:
                    stack.append((u, v, path + [u]))
    return None

