# Let me also check all cycles systematically
def enumerate_all_cycles_up_to(graph, n, max_len):
    adj = {i: set() for i in range(n)}
    for u, v in graph:
        adj[u].add(v)
        adj[v].add(u)

    cycles = []
    for start in range(n):
        # DFS
        stack = [(start, -1, [start], set([start]))]
        while stack:
            v, parent, path, path_set = stack.pop()
            for u in adj[v]:
                if u == parent:
                    continue
                if u == start and len(path) >= 3 and len(path) <= max_len:
                    cycles.append(path + [start])
                elif u not in path_set and len(path) < max_len:
                    stack.append((u, v, path + [u], path_set | {u}))
    # Deduplicate cycles (same set of vertices)
    unique = set()
    for c in cycles:
        unique.add(tuple(sorted(c[:-1])))  # exclude the repeated start
    return [list(c) for c in unique]

short_cycles = enumerate_all_cycles_up_to(graph, n, 7)
