def shortest_cycle_through(graph, n, start):
    adj = {i: set() for i in range(n)}
    for u, v in graph:
        adj[u].add(v)
        adj[v].add(u)

    # BFS
    dist = {start: 0}
    parent = {start: -1}
    queue = [start]
    min_cycle = float('inf')

    while queue:
        v = queue.pop(0)
        for u in adj[v]:
            if u == parent[v]:
                continue
            if u not in dist:
                dist[u] = dist[v] + 1
                parent[u] = v
                queue.append(u)
            elif u != parent[v]:
                # Found a cycle
                cycle_len = dist[v] + dist[u] + 1
                if cycle_len < min_cycle:
                    min_cycle = cycle_len
    return min_cycle

