def find_cycle_of_length(graph, n, length):
    adj = {i: set() for i in range(n)}
    for u, v in graph:
        adj[u].add(v)
        adj[v].add(u)

    for start in range(n):
        stack = [(start, -1, [start])]
        while stack:
            v, parent, path = stack.pop()
            for u in adj[v]:
                if u == parent:
                    continue
                if u == start and len(path) == length:
                    return path + [start]
                if u not in path and len(path) < length:
                    stack.append((u, v, path + [u]))
    return None

